class Solution:
    def jump(self, nums: List[int]) -> int:
        jumps, cur_end, furthest = 0, 0, 0
        for i in range(len(nums) - 1):
            furthest = max(furthest, i + nums[i])
            if i == cur_end:
                jumps += 1
                cur_end = furthest
        return jumps

